import pytest

import flask


@pytest.mark.parametrize("code", [None, 301, 302, 303, 305, 307, 308])
@pytest.mark.parametrize("custom_response", [False, True])
def test_app_redirect(app, code, custom_response):
    if custom_response:
        class CustomResponse(flask.Response):
            pass

        app.response_class = CustomResponse

    assert not flask.has_app_context()

    if code is None:
        response = app.redirect("/target?next=1&other=2")
    else:
        response = app.redirect("/target?next=1&other=2", code=code)

    assert type(response) is app.response_class
    assert response.status_code == (302 if code is None else code)
    assert response.location == "/target?next=1&other=2"
    assert response.mimetype == "text/html"
    assert b"/target?next=1&amp;other=2" in response.data

